const D = { tone: .5, wipe: .5, energy: .5, speed: 1, hue: 30, plate: .35, grain: .5, scale: 1, x: .5, y: .5, alpha: 78, act: 'wipe', style: 'intaglio', seed: 0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const clp = (v, a, b) => v < a ? a : v > b ? b : v;
const fr = i => { const s = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return s - Math.floor(s); };
const hsh = (x, y) => { const s = Math.sin(x * 127.1 + y * 311.7 + P.seed * 74.7) * 43758.5453; return s - Math.floor(s); };
const vn = (x, y) => {
  const xi = Math.floor(x), yi = Math.floor(y), xf = x - xi, yf = y - yi;
  const u2 = xf * xf * (3 - 2 * xf), v2 = yf * yf * (3 - 2 * yf);
  const a = hsh(xi, yi), b = hsh(xi + 1, yi), c = hsh(xi, yi + 1), d = hsh(xi + 1, yi + 1);
  return (a * (1 - u2) + b * u2) * (1 - v2) + (c * (1 - u2) + d * u2) * v2;
};
const fbm = (x, y, o) => { let s = 0, am = .5, f = 1; for (let i = 0; i < o; i++) { s += am * vn(x * f, y * f); am *= .5; f *= 2.03; } return s; };
const rgbv = (h, s, v) => {
  h = ((h % 360) + 360) % 360 / 60; const c = v * s, xx = c * (1 - Math.abs(h % 2 - 1)), m = v - c; let r, g2, b2;
  if (h < 1) { r = c; g2 = xx; b2 = 0; } else if (h < 2) { r = xx; g2 = c; b2 = 0; } else if (h < 3) { r = 0; g2 = c; b2 = xx; }
  else if (h < 4) { r = 0; g2 = xx; b2 = c; } else if (h < 5) { r = xx; g2 = 0; b2 = c; } else { r = c; g2 = 0; b2 = xx; }
  return [(r + m) * 255, (g2 + m) * 255, (b2 + m) * 255];
};
const css = (h, s, v, a) => { const c = rgbv(h, s, v); return 'rgba(' + Math.round(c[0]) + ',' + Math.round(c[1]) + ',' + Math.round(c[2]) + ',' + a + ')'; };

const W = width, H = height, u = Math.min(W, H), dc = drawingContext;
const tn = clp(P.tone, 0, 1), wp = clp(P.wipe, 0, 1), en = clp(P.energy, 0, 1);
const gr = clp(P.grain, 0, 1), pl = clp(P.plate, 0, 1);
const sp = Math.max(.1, P.speed), sc = Math.max(.3, P.scale);
const st = P.style, hb = ((P.hue % 360) + 360) % 360, la = clp(P.alpha, 0, 100) / 100;
const bleach = st === 'bleached';

let inkH = hb, inkS = .42, inkV = .10, paH = hb + 14, paS = .11, paV = .93, foul = 1, veil = 1;
if (st === 'aquatint') { inkH = hb + 186; inkS = .22; inkV = .13; paH = hb + 20; paS = .06; paV = .94; foul = 1.9; }
else if (st === 'retroussage') { inkH = hb - 4; inkS = .34; inkV = .08; paH = hb + 16; paS = .13; paV = .92; foul = .5; veil = 2.3; }
else if (st === 'drypoint') { inkH = hb + 6; inkS = .30; inkV = .05; paH = hb + 12; paS = .10; paV = .93; foul = .8; veil = 1.5; }
else if (bleach) { inkH = hb + 18; inkS = .10; inkV = .96; paH = hb + 18; paS = .05; paV = .97; foul = .6; }

// ---- act ---------------------------------------------------------------------
let filmM = 1;
if (P.act === 'proof') filmM = .55 + .35 * (.5 + .5 * Math.sin(K.t * .0127 + 1.7));
else if (P.act === 'edition') filmM = .85 + .95 * (.5 + .5 * Math.sin(K.t * .0059 + .7 * Math.sin(K.t * .0023 + 2.5)));
else filmM = .78 + .5 * (.5 + .5 * Math.sin(K.t * .0089 + .6 * Math.sin(K.t * .0031 + 1.2)));
filmM *= (.8 + .4 * K.intensity);

const sq = Math.round(sc * 6), hq = Math.round(hb / 8);
// ---- the plate: residual ink film + foul bite (drifts — every pull is re-wiped)
const TW = Math.max(220, Math.min(560, Math.round(W * .34))), TH = Math.max(130, Math.round(TW * H / W));
if (!S.tn || S.tw !== TW || S.th !== TH || S.tseed !== P.seed || S.tsty !== st || S.tsq !== sq || S.thq !== hq) {
  if (S.tn && S.tn.remove) S.tn.remove();
  S.tn = createGraphics(TW, TH); S.tn.pixelDensity(1);
  S.tw = TW; S.th = TH; S.tseed = P.seed; S.tsty = st; S.tsq = sq; S.thq = hq;
  const ic = rgbv(inkH, inkS, inkV), pc = rgbv(paH, paS, paV);
  const f = .022 / sc;
  S.tn.loadPixels(); const tp = S.tn.pixels;
  for (let y = 0; y < TH; y++) for (let x = 0; x < TW; x++) {
    let m = .30 + .62 * fbm(x * f, y * f, 4) + .18 * (fbm(x * f * 5.1 + 11, y * f * 5.1 + 7, 3) - .5);
    // foul bite: the acid crept under the ground in patches
    const fb = fbm(x * f * 2.7 + 31, y * f * 2.7 + 17, 3);
    if (fb > .60) m += (fb - .60) * 2.4 * foul;
    m += (hsh(x * .77 + y * .19, y * .83 + x * .27) - .5) * .10;
    m = clp(m, 0, 1);
    const o = 4 * (y * TW + x);
    if (bleach) { tp[o] = pc[0] * m; tp[o + 1] = pc[1] * m; tp[o + 2] = pc[2] * m; }
    else { tp[o] = 255 + (ic[0] - 255) * m; tp[o + 1] = 255 + (ic[1] - 255) * m; tp[o + 2] = 255 + (ic[2] - 255) * m; }
    tp[o + 3] = 255;
  }
  S.tn.updatePixels();
}
// ---- the paper: laid lines, chain lines, rag fibre (registered, does not drift)
const PW = Math.max(280, Math.min(720, Math.round(W * .44))), PH = Math.max(160, Math.round(PW * H / W));
if (!S.pap || S.pw !== PW || S.ph !== PH || S.pseed !== P.seed || S.psq !== sq) {
  if (S.pap && S.pap.remove) S.pap.remove();
  S.pap = createGraphics(PW, PH); S.pap.pixelDensity(1);
  S.pw = PW; S.ph = PH; S.pseed = P.seed; S.psq = sq;
  const lf = .62 / sc, cf = 7 / sc;
  S.pap.loadPixels(); const pp = S.pap.pixels;
  for (let y = 0; y < PH; y++) for (let x = 0; x < PW; x++) {
    const f1 = hsh(x * .89 + y * .21, y * .93 + x * .13);
    const f2 = hsh(x * .29 - y * .41 + 4.7, y * .33 + x * .49 + 9.1);
    const fib = Math.pow(clp(f1 * .78 + f2 * .5 - .13, 0, 1), 1.2);
    const laid = .5 + .5 * Math.sin(y * lf + vn(x * .015, y * .015) * 2.6);
    const ch = (Math.abs(((x / PW * cf) % 1) - .5) < .028) ? 1 : 0;
    const v = 255 - 46 * fib - 15 * laid - 14 * ch;
    const o = 4 * (y * PW + x); pp[o] = v; pp[o + 1] = v; pp[o + 2] = v; pp[o + 3] = 255;
  }
  S.pap.updatePixels();
}

// ---- lay the pass down -------------------------------------------------------
const oldA = dc.globalAlpha, oldOp = dc.globalCompositeOperation;
noStroke();
// residual ink film — the drift is the plate being wiped again for the next pull
const ox = u * .03 * (Math.sin(K.t * .073 * sp) + .55 * Math.sin(K.t * .169 * sp + 1.2));
const oy = u * .026 * (Math.sin(K.t * .097 * sp + 2.1) + .55 * Math.sin(K.t * .211 * sp));
const zm = u * .04 * (1 + .3 * Math.sin(K.t * .053 + .8));
blendMode(bleach ? SCREEN : MULTIPLY);
dc.globalAlpha = la * clp(tn * 1.15 * filmM, 0, 1);
dc.drawImage(S.tn.drawingContext.canvas, ox - zm, oy - zm, W + zm * 2, H + zm * 2);
// rag paper, pressed into the ink
blendMode(MULTIPLY);
dc.globalAlpha = la * gr * .9;
dc.drawImage(S.pap.drawingContext.canvas, 0, 0, W, H);
blendMode(BLEND);

// hand-wiped streaks, dragged across the plate in one direction
const wang = .5 + .55 * Math.sin(K.t * .019 * sp + .7 * Math.sin(K.t * .0071 + 1.4));
const L = Math.sqrt(W * W + H * H) * 1.12;
const nst = 4 + Math.round(wp * 6);
dc.save();
dc.translate(W * .5, H * .5); dc.rotate(wang);
for (let k = 0; k < nst; k++) {
  const q = j => fr(k * 7.3 + j * 1.7 + 5);
  const th = L * (.012 + .075 * q(1)) * veil;
  const yy = ((q(2) + .06 * Math.sin(K.t * .041 * sp + k * 2.1)) - .5) * L;
  const dark = q(3) < .55;
  const ch2 = dark ? inkH : paH, cs2 = dark ? inkS : paS, cv2 = dark ? inkV : paV;
  const a2 = la * wp * (.06 + .30 * q(4)) * (dark ? filmM : 1) * (bleach ? .6 : 1);
  const g2 = dc.createLinearGradient(0, yy, 0, yy + th);
  g2.addColorStop(0, css(ch2, cs2, cv2, 0));
  g2.addColorStop(.5, css(ch2, cs2, cv2, clp(a2, 0, 1)));
  g2.addColorStop(1, css(ch2, cs2, cv2, 0));
  dc.globalAlpha = 1; dc.fillStyle = g2;
  dc.fillRect(-L * .5, yy, L, th);
