dc.restore();

// ---- the plate mark: an inked slab pressed into a bigger sheet ---------------
if (pl > .02) {
  const ins = u * (.008 + pl * .105);
  const ix = ins * (.92 + .16 * fr(11)), iy = ins * (.9 + .2 * fr(12));
  const bx = W - ins * (.92 + .16 * fr(13)), by = H - ins * (.9 + .2 * fr(14));
  const jx = u * .0022 * Math.sin(K.t * .057 + .5), jy = u * .0018 * Math.sin(K.t * .081 + 2.3);
  const x0 = ix + jx, y0 = iy + jy, x1 = bx + jx, y1 = by + jy;
  // the margin is bare paper
  dc.globalAlpha = la * clp(.55 + pl * .45, 0, 1);
  dc.fillStyle = css(paH, paS, paV * (bleach ? 1 : .97), 1);
  dc.beginPath(); dc.rect(0, 0, W, H); dc.rect(x0, y0, x1 - x0, y1 - y0); dc.fill('evenodd');
  // ink piles up against the bevel and prints as a dark line
  dc.globalAlpha = la * clp(.35 + tn * .55, 0, 1) * (st === 'drypoint' ? 1.3 : 1);
  dc.strokeStyle = css(inkH, inkS, inkV, 1); dc.lineWidth = Math.max(1, u * .0035 * (.6 + tn));
  dc.strokeRect(x0, y0, x1 - x0, y1 - y0);
  // the bevel deboss, read by the same raking lamp
  const ba = K.t * .11 * sp + .8 * Math.sin(K.t * .043 + .6) + .3 * Math.sin(K.t * .107 + 2.2);
  const bdx = Math.cos(ba) * u * .0035 * (.5 + en), bdy = Math.sin(ba) * u * .0035 * (.5 + en);
  dc.lineWidth = Math.max(1, u * .0045);
  dc.globalAlpha = la * (.30 + .45 * en);
  dc.strokeStyle = 'rgba(255,252,244,1)';
  dc.strokeRect(x0 - bdx * 1.6, y0 - bdy * 1.6, x1 - x0, y1 - y0);
  dc.globalAlpha = la * (.34 + .5 * en);
  dc.strokeStyle = 'rgba(24,18,12,1)';
  dc.strokeRect(x0 + bdx * 1.6, y0 + bdy * 1.6, x1 - x0, y1 - y0);
}

// ---- damp paper catching the gallery light -----------------------------------
const shp = K.t * .09 * sp + .7 * Math.sin(K.t * .037 + 1.1) + .28 * Math.sin(K.t * .083);
const c0 = clp(.5 + .46 * Math.sin(shp), .04, .96);
const sga = dc.createLinearGradient(W * (P.x - .6), H * (P.y - .6), W * (P.x + .6), H * (P.y + .6));
sga.addColorStop(Math.max(0, c0 - .34), 'rgba(255,250,236,0)');
sga.addColorStop(c0, 'rgba(255,250,236,' + (.03 + .16 * en * (1 + .3 * K.swell + .4 * A.rms)).toFixed(3) + ')');
sga.addColorStop(Math.min(1, c0 + .34), 'rgba(255,250,236,0)');
dc.globalAlpha = la; dc.fillStyle = sga; dc.fillRect(0, 0, W, H);

dc.globalAlpha = oldA; dc.globalCompositeOperation = oldOp;
blendMode(BLEND);
dc.shadowBlur = 0;
